def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    own = []
    opp = []
    for mine, theirs in history:
        own.append(mine)
        opp.append(theirs)

    opp_c = 0
    own_d = 0
    for i in range(n):
        if opp[i] == 'C':
            opp_c += 1
        if own[i] == 'D':
            own_d += 1

    opp_d = n - opp_c

    l10 = min(n, 10)
    rec10_opp_c = 0
    for i in range(n - l10, n):
        if opp[i] == 'C':
            rec10_opp_c += 1

    l6 = min(n, 6)
    rec6_own_d = 0
    for i in range(n - l6, n):
        if own[i] == 'D':
            rec6_own_d += 1

    l3 = min(n, 3)
    rec3_opp_c = 0
    for i in range(n - l3, n):
        if opp[i] == 'C':
            rec3_opp_c += 1

    dc_c = 0
    dc_d = 0
    for i in range(1, n):
        if own[i - 1] == 'D':
            if opp[i] == 'C':
                dc_c += 1
            else:
                dc_d += 1

    start = n - 10
    if start < 1:
        start = 1

    rdc_c = 0
    rdc_d = 0
    for i in range(start, n):
        if own[i - 1] == 'D':
            if opp[i] == 'C':
                rdc_c += 1
            else:
                rdc_d += 1

    last_own = own[-1]
    last_opp = opp[-1]

    bdr = 0
    for i in range(n - 1, -1, -1):
        if own[i] == 'D' and opp[i] == 'D':
            bdr += 1
        else:
            break

    cdrun = 0
    for i in range(n - 1, -1, -1):
        if own[i] == 'C' and opp[i] == 'D':
            cdrun += 1
        else:
            break

    if opp_d * 4 >= n * 3 or rec10_opp_c * 4 < l10:
        if bdr >= 5 and opp_c >= 3 and rec3_opp_c >= 1 and rng.random() < 0.15:
            return 'C'
        return 'D'

    if rdc_c > 0 and rdc_c > rdc_d:
        if opp_c * 20 >= n * 9 and rec10_opp_c * 5 >= l10 * 2:
            return 'D'

    if n >= 5 and rec6_own_d == 0 and rdc_d == 0 and own_d <= 3:
        if opp_c * 2 >= n and rec10_opp_c * 2 >= l10:
            return 'D'

    if n >= 85 and dc_c > 0 and dc_d == 0 and opp_c * 3 >= n * 2:
        return 'D'

    if last_opp == 'C':
        return 'C'

    if last_own == 'D':
        if rec3_opp_c == 0:
            if bdr >= 7 and opp_c >= 5 and rng.random() < 0.05:
                return 'C'
            return 'D'
        if bdr <= 2:
            return 'C'
        if bdr >= 7 and opp_c >= 5 and rng.random() < 0.05:
            return 'C'
        return 'D'

    if cdrun >= 2:
        return 'D'

    if rec6_own_d == 0 and rdc_d == 0:
        if opp_c * 2 >= n and rec10_opp_c * 2 >= l10:
            return 'D'

    return 'C'
